#!/bin/bash\n\nset -euo pipefail\n\nSNAPSHOT_PREFIX="temporal-echo-snapshot-"\n\n_help() {\n    echo "Usage: $0 <command> [arguments]\n\nCommands:\n  save <container_name> <snapshot_name>  - Saves the current state of a running container as a snapshot.\n  load <snapshot_name> <new_container_name> - Creates and runs a new container from a saved snapshot.\n  list                                    - Lists all available temporal echoes (snapshots).\n  delete <snapshot_name>                  - Deletes a specific temporal echo (snapshot image).\n  help                                    - Show this help message.\n"\n}\n\n_save() {\n    local container_name="$1"\n    local snapshot_name="$2"\n    if [[ -z "$container_name" || -z "$snapshot_name" ]]; then\n        echo "Error: Both container_name and snapshot_name are required for 'save'." >&2\n        _help\n        exit 1\n    fi\n\n    echo "Saving temporal echo for container '$container_name' as '$snapshot_name'..."\n    docker commit "$container_name" "${SNAPSHOT_PREFIX}${snapshot_name}"\n    echo "Snapshot '${snapshot_name}' saved successfully."\n}\n\n_load() {\n    local snapshot_name="$1"\n    local new_container_name="$2"\n    if [[ -z "$snapshot_name" || -z "$new_container_name" ]]; then\n        echo "Error: Both snapshot_name and new_container_name are required for 'load'." >&2\n        _help\n        exit 1\n    fi\n\n    local image_name="${SNAPSHOT_PREFIX}${snapshot_name}"\n    if ! docker images --format "{{.Repository}}" | grep -q "^${image_name}$"; then\n        echo "Error: Snapshot '${snapshot_name}' not found." >&2\n        exit 1\n    fi\n\n    echo "Loading temporal echo '${snapshot_name}' into new container '$new_container_name'..."\n    docker run -d --name "$new_container_name" "$image_name"\n    echo "Container '$new_container_name' created and running from snapshot '${snapshot_name}'."\n}\n\n_list() {\n    echo "Available Temporal Echoes (Snapshots):"\n    docker images --format "{{.Repository}}" | grep "^${SNAPSHOT_PREFIX}" | sed "s/^${SNAPSHOT_PREFIX}//" || echo "  No snapshots found."
}\n\n_delete() {\n    local snapshot_name="$1"\n    if [[ -z "$snapshot_name" ]]; then\n        echo "Error: snapshot_name is required for 'delete'." >&2\n        _help\n        exit 1\n    fi\n\n    local image_name="${SNAPSHOT_PREFIX}${snapshot_name}"\n    if ! docker images --format "{{.Repository}}" | grep -q "^${image_name}$"; then\n        echo "Error: Snapshot '${snapshot_name}' not found." >&2\n        exit 1\n    fi\n\n    echo "Deleting temporal echo '${snapshot_name}'..."\n    docker rmi "$image_name"\n    echo "Snapshot '${snapshot_name}' deleted successfully."\n}\n\ncase "$1" in\n    save)\n        _save "$2" "$3"\n        ;;\n    load)\n        _load "$2" "$3"\n        ;;\n    list)\n        _list\n        ;;\n    delete)\n        _delete "$2"\n        ;;\n    help|--help|-h|*) # Default to help if no command or unknown command\n        _help\n        exit 0\n        ;;\nesac
